INSERT INTO `Items_Attributes_Values` VALUES (37,1,'The original/star 16th printing (Australia) was released with a purple colored spine.'),(45,1,'This title was first published in the green zigzag format, and was reissued in all of the original series formats except for the dragon/bronze text/unnumbered variation.'),(52,1,'The text of the book was revised in 1987 with the sixth printing (and the transition from the \"zigzag\" to \"number front\" format). The most visible change is the renaming of \"pep pills\" to \"energy tablets.\" The American Dell edition predates these revisions and thus includes the original unrevised text.'),(63,1,'Thanks to Ryan Lynch for the images.'),(109,1,'Thanks to Ryan Lynch for the images.'),(13046,1,'Some online images of the cover of this book do not include the word \"Deluxe.\" It is unclear whether there are two versions of the book, or simply some inconsistent promotional images.'),(13435,1,'This book is only available to buyers of the \"Judicator Supporter Pack\" or the \"Orion Supporter Pack\" for the video game \"Path of Exile\".'),(14481,1,'This box contains extra space so that it can store <i>Sherlock Holmes: The Beginning</i>, which was published between seasons 3 and 4.');
/*!40000 ALTER TABLE `Items_Attributes_Values` ENABLE KEYS */;
