DROP TABLE IF EXISTS `Links`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Links` (
  `Link_ID` int NOT NULL AUTO_INCREMENT,
  `Link_Name` tinytext NOT NULL,
  `URL` tinytext NOT NULL,
  `Description` tinytext,
  `Date_Checked` date NOT NULL DEFAULT '0000-00-00',
  `Link_Type_ID` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`Link_ID`),
  KEY `Link_Type_ID` (`Link_Type_ID`),
  CONSTRAINT `Links_ibfk_1` FOREIGN KEY (`Link_Type_ID`) REFERENCES `Link_Types` (`Link_Type_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=276 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

