  KEY `Series_ID` (`Series_ID`),
  KEY `Note_ID` (`Note_ID`),
  CONSTRAINT `Series_AltTitles_ibfk_1` FOREIGN KEY (`Series_ID`) REFERENCES `Series` (`Series_ID`),
  CONSTRAINT `Series_AltTitles_ibfk_2` FOREIGN KEY (`Note_ID`) REFERENCES `Notes` (`Note_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=247 DEFAULT CHARSET=utf8mb3;
